import * as T from 'three';
import {box,cylinder} from './models.js';
export function installSceneLighting(world,e){if(e.id!=='FPTSR'&&e.kind!=='EPA')return;const aerial=e.kind==='EPA',mount=new T.Group(),parent=aerial?e.model.userData.ladder:e.model;parent.add(mount);mount.position.set(0,aerial?.75:3.25,aerial?6.2:-1.5);const pole=aerial?null:cylinder(mount,.085,.1,1,'#c4cccd',0,.5,0,10),head=new T.Group();mount.add(head);const lights=[];for(const [x,z]of[[-1,-1],[1,-1],[-1,1],[1,1]]){const lamp=box(head,.35,.22,.18,new T.MeshStandardMaterial({color:'#dddccf',emissive:'#fff2cb',emissiveIntensity:0}),x*.32,0,z*.2);const light=new T.SpotLight('#fff0cf',0,55,.82,.6,1.4);light.position.set(x*.32,0,z*.2);head.add(light);const target=new T.Object3D();world.add(target);light.target=target;light.castShadow=false;light.visible=false;lights.push({lamp,light,target,x,z});}e.zoneLightRig={pole,head,lights,aerial,extension:0};}
export function updateSceneLighting(e,dt){const rig=e.zoneLightRig;if(!rig)return;const active=!!e.zoneLighting&&['scene','reconditioning'].includes(e.status);if(!active)e.zoneLighting=false;rig.extension=Math.max(0,Math.min(1,rig.extension+(active?1:-1)*dt/2));if(rig.pole){rig.pole.scale.y=Math.max(.08,rig.extension*2.8);rig.pole.position.y=rig.extension*1.4;rig.head.position.y=rig.extension*2.8;}for(const {lamp,light,target,x,z}of rig.lights){target.position.set(e.model.position.x+x*10,.1,e.model.position.z+z*10);const on=active&&(rig.aerial||rig.extension>=.98);lamp.material.emissiveIntensity=on?4:0;light.intensity=on?450:0;light.visible=on;}}
